#!/usr/bin/env node
// Generates src/ui/icons/spriteIndex.ts from the one authored sprite, src/ui/icons/sprite.svg (brand-ui SPEC section 7):
// the IconId union, the ids that own a 16-unit optical master or take the filled active state, and the boot slice
// (BOOT_ICON_IDS, mounted synchronously before the full sprite's lazy chunk arrives), plus the few standalone SVG files
// a page cannot reference through the sprite (the Studio's browser-tab mark, the README's pictograms). Idempotent;
// `--check` fails when any generated file drifts from the sprite.
//   node tools/gen-icon-sprite.mjs [--check]
// Copyright © 2026 Kevin B. Liu.
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { ACTIVE_ICON_IDS, ID_PREFIX, SMALL_SUFFIX, parseIconSprite } from './icon-sprite-lib.mjs';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const SPRITE = resolve(root, 'src/ui/icons/sprite.svg');
const OUT = resolve(root, 'src/ui/icons/spriteIndex.ts');

const ACCENT = '#f0a030';
const TILE = '#0b0e11';
/** Standalone exports: a browser-tab mark on a graphite tile, and accent pictograms for the repository README. */
const STANDALONE_ICONS = Object.freeze([
  { file: 'public/brand/studio-tab.svg', id: 'studio', tile: true },
  ...['play', 'manual', 'gallery', 'studio', 'layerModules', 'fireGun', 'layerArmor', 'toolPhoto', 'cameraPath', 'vehicle',
    'rocket', 'map', 'gpu', 'team'].map((id) => ({ file: `docs/media/icons/${id}.svg`, id, tile: false })),
]);

/** One glyph as a self-contained SVG file in the accent colour (no sprite, no currentColor context). */
function standaloneIconSvg(body, { tile = false } = {}) {
  const glyph = body.replaceAll('currentColor', ACCENT);
  const plate = tile ? `<path d="M2 0h20l2 2v20l-2 2H2l-2-2V2Z" fill="${TILE}" stroke="none"/>` : '';
  return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="64" height="64" fill="none" '
    + `stroke="${ACCENT}" stroke-width="1.5" stroke-linecap="square" stroke-linejoin="miter">`
    + `<!-- Claude of Tanks UI icon. Copyright (c) 2026 Kevin B. Liu. Generated from src/ui/icons/sprite.svg. -->`
    + `${plate}${glyph}</svg>\n`;
}

/** The glyphs the first frame can show before the lazy sprite lands: the game bar and its controls (SPEC 16.1). */
const BOOT_ICON_IDS = Object.freeze([
  'home', 'record', 'garage', 'deploy', 'gallery', 'manual', 'studio', 'settings', 'github', 'chevronDown', 'close',
  'sound',
]);

function generateSpriteIndex(spriteText) {
  const { large, small } = parseIconSprite(spriteText);
  for (const id of [...BOOT_ICON_IDS, ...ACTIVE_ICON_IDS]) {
    if (!large.has(id)) throw new Error(`gen-icon-sprite: listed id "${id}" has no symbol in sprite.svg`);
  }
  const ids = [...large.keys()];
  const boot = [];
  for (const id of BOOT_ICON_IDS) {
    boot.push(`<symbol id="${ID_PREFIX}${id}">${large.get(id)}</symbol>`);
    if (small.has(id)) boot.push(`<symbol id="${ID_PREFIX}${id}${SMALL_SUFFIX}">${small.get(id)}</symbol>`);
  }
  const list = (values) => ` ${values.join(' ')} `;
  const union = ids.map((id) => `  | '${id}'`).join('\n');
  return `// Generated by tools/gen-icon-sprite.mjs from src/ui/icons/sprite.svg. Do not edit by hand: edit the sprite and run
// \`node tools/gen-icon-sprite.mjs\`. Copyright © 2026 Kevin B. Liu.

/** Every glyph in the sprite (${ids.length}), by its public id. */
export type IconId =
${union};

/** Every icon id, in sprite order (tests and the icon sheet; never needed by a runtime surface). */
export const ICON_IDS: readonly IconId[] = ${JSON.stringify(ids)};

/** Ids with a 16-unit optical master, space-delimited with a leading and trailing space. */
export const SMALL_MASTERS = '${list([...small.keys()])}';

/** Ids drawn to take the filled active state (closed bodies, evenodd knock-outs), same format. */
export const ACTIVE_MASTERS = '${list([...ACTIVE_ICON_IDS])}';

/** The boot slice: ${BOOT_ICON_IDS.length} glyphs mounted synchronously, before the full sprite's lazy chunk arrives. */
export const BOOT_SYMBOLS = '${boot.join('').replace(/'/g, "\\'")}';
`;
}

const isMain = process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain) {
  const spriteText = readFileSync(SPRITE, 'utf8');
  const { large } = parseIconSprite(spriteText);
  const outputs = [[OUT, generateSpriteIndex(spriteText)]];
  for (const { file, id, tile } of STANDALONE_ICONS) {
    if (!large.has(id)) throw new Error(`gen-icon-sprite: standalone id "${id}" has no symbol`);
    outputs.push([resolve(root, file), standaloneIconSvg(large.get(id), { tile })]);
  }
  if (process.argv.includes('--check')) {
    const stale = outputs.filter(([file, text]) => {
      try { return readFileSync(file, 'utf8') !== text; } catch { return true; }
    });
    if (stale.length) {
      console.error(`gen-icon-sprite: stale ${stale.map(([file]) => file.slice(root.length + 1)).join(', ')}; `
        + 'run `node tools/gen-icon-sprite.mjs`');
      process.exit(1);
    }
    console.log(`gen-icon-sprite: ${outputs.length} generated files match sprite.svg`);
  } else {
    for (const [file, text] of outputs) {
      mkdirSync(dirname(file), { recursive: true });
      writeFileSync(file, text);
    }
    console.log(`gen-icon-sprite: wrote ${outputs.length} files`);
  }
}
